class ManagedObjectLabel(object):
    _blacklist = ["MRBTS", "LNBTS", "FTM"]

    def __init__(self, object_path, to_replace=None):
        self._to_replace = self.get_to_replace_dict(to_replace)
        self._object_path = object_path
        self._object_sequence = self.get_object_sequence()
        self._name = self.get_name()
        self._class = self.get_class()
        self._index = self.get_index()
        self._parent = ManagedObjectLabel(self.get_parent_path(), to_replace) if self.has_parent() else None

    def get_to_replace_dict(self, to_replace_dict):
        if to_replace_dict is None:
            to_replace_dict = {}
        return to_replace_dict

    def get_index(self):
        return self._name.split("-")[-1]

    def get_object_sequence(self):
        return self._object_path.split("/")

    def get_name(self):
        return self._object_sequence[-1]

    def has_parent(self):
        return len(self._object_sequence) >= 2

    def get_class(self):
        return self._name.split("-")[0]

    def get_parent_path(self):
        return "/".join(self._object_sequence[:-1])

    def is_blacklisted(self):
        return self._class in self._blacklist

    def get_yaml_name(self):
        return self._class + "-%s" % self.get_yaml_index()

    def get_emss_name(self):
        return self._class + "-%s" % self.get_emss_index()

    def get_yaml_index(self):
        index_sequence = [self.get_fake_index()]
        iter = self
        while iter.has_parent() and not iter._parent.is_blacklisted():
            index_sequence.insert(0, iter._parent.get_fake_index())
            iter = iter._parent
        return "-".join(index_sequence)

    def get_emss_index(self):
        index_sequence = [self.get_index()]
        if self.has_parent() and not self._parent.is_blacklisted():
            index_sequence.insert(0, self._parent.get_index())
        return "-".join(index_sequence)

    def is_to_replace(self):
        return self._name in self._to_replace

    def get_fake_index(self):
        if self.is_to_replace():
            fake_index = "${%s}" % self._to_replace[self._name]
        else:
            fake_index = self._index
        return fake_index
